from pathlib import Path
from html.parser import HTMLParser
import gzip,json,re,hashlib,base64
from PIL import Image
ROOT=Path('/home/user/PROJECT_LEO_PHASE_B_2026-11-04_v1')
# Markup is generated by the final isolated VM test. This is not an accessibility-engine/browser audit.
rendered=json.loads(gzip.decompress((ROOT/'evidence/RENDERED_SCREEN_MARKUP_final.json.gz').read_bytes()))
class Check(HTMLParser):
 def __init__(self):super().__init__();self.stack=[];self.buttons=[];self.labels=set();self.inputs=[];self.duplicates=[];self.radio_parents=[];self.has_fa=False;self.has_en=False
 def handle_starttag(self,tag,attrs):
  a=dict(attrs)
  if len(a)!=len(attrs):self.duplicates.append(tag)
  if a.get('lang')=='fa' and a.get('dir')=='rtl':self.has_fa=True
  if a.get('lang')=='en' or a.get('dir')=='ltr':self.has_en=True
  if tag=='label' and a.get('for'):self.labels.add(a['for'])
  if tag in ['input','select','textarea']:self.inputs.append(a)
  if tag=='button':self.buttons.append({'attrs':a,'text':''})
  if a.get('role')=='radio':self.radio_parents.append(any(x[1].get('role')=='radiogroup' for x in self.stack))
  if tag not in ['input','img','br','hr','meta','link','source','path','use']:self.stack.append((tag,a,len(self.buttons)-1 if tag=='button' else None))
 def handle_startendtag(self,tag,attrs):pass
 def handle_endtag(self,tag):
  for i in range(len(self.stack)-1,-1,-1):
   if self.stack[i][0]==tag:self.stack=self.stack[:i];break
 def handle_data(self,data):
  for tag,a,index in self.stack:
   if tag=='button' and index is not None and index<len(self.buttons):self.buttons[index]['text']+=data
results=[]
for id,markup in rendered.items():
 p=Check();p.feed(markup)
 no_names=[b['attrs'].get('data-action','unknown') for b in p.buttons if not(b['text'].strip() or b['attrs'].get('aria-label') or b['attrs'].get('aria-labelledby'))]
 unlabeled=[i.get('id','no-id') for i in p.inputs if not(i.get('aria-label') or i.get('aria-labelledby') or i.get('id') in p.labels)]
 results.append({'screen':id,'button_count':len(p.buttons),'unnamed_buttons':no_names,'unlabeled_fields':unlabeled,'duplicate_attribute_tags':p.duplicates,'radio_without_group':sum(not x for x in p.radio_parents),'persian_region_declared':p.has_fa,'english_or_ltr_region_declared':p.has_en})
issues=[x for x in results if x['unnamed_buttons'] or x['unlabeled_fields'] or x['duplicate_attribute_tags'] or x['radio_without_group']]
html=(ROOT/'prototype/LEO_DESIGN_PROTOTYPE_v6.html').read_text()
network=[]
class Resources(HTMLParser):
 def handle_starttag(self,t,attrs):
  for k,v in attrs:
   if k in ['src','href'] and not(v.startswith('data:') or v.startswith('#')):network.append((t,k))
Resources().feed(html)
assert not network
# All active PNG designs use actual alpha; original source PNG exports are excluded.
art=json.loads((ROOT/'evidence/LEO_RASTER_VALIDATION_v3.json').read_text())['active_assets']
alpha=[]
for a in art:
 with Image.open(ROOT/a['png']) as im:
  ok=im.mode=='RGBA' and im.getchannel('A').getextrema()==(0,255)
  alpha.append({'file':a['png'],'mode':im.mode,'size':list(im.size),'alpha_pass':ok})
assert all(a['alpha_pass'] for a in alpha)
report={'method':'Static HTMLParser inspection of simulated-DOM render output, not a browser/axe/TalkBack run','screens':results,'issues':issues,'external_runtime_resources':network,'active_character_alpha':alpha,'actual_browser_focus_keyboard_layout':'NOT TESTED','native_dp_and_sp':'NOT TESTED'}
with (ROOT/'evidence/STATIC_MARKUP_REVIEW.json').open('x') as f:json.dump(report,f,ensure_ascii=False,indent=2)
print('Screens statically inspected:',len(results),'markup issues:',len(issues))
for x in issues:print(x)
print('Active character alpha checks:',len(alpha),'PASS; no external runtime resource URLs.')
